import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_c = 0
    my_c = 0
    for me, op in history:
        if op == 'C':
            opp_c += 1
        if me == 'C':
            my_c += 1
    opp_d = n - opp_c
    defect_rate = opp_d / n

    # Always-cooperative opponent: cooperate, exploit at very end
    if opp_d == 0:
        if n >= 96:
            return 'D'
        return 'C'

    # Always-defecting opponent: defect
    if opp_c == 0:
        return 'D'

    # Detect recent opponent behavior
    window = history[-12:]
    recent_opp_c = sum(1 for _, o in window if o == 'C')
    recent_opp_d = len(window) - recent_opp_c
    recent_rate = recent_opp_c / len(window)

    last_me, last_op = history[-1]

    # Count consecutive opponent defections at tail
    run_d = 0
    for me, op in reversed(history):
        if op == 'D':
            run_d += 1
        else:
            break

    # Count consecutive opponent cooperations at tail
    run_c = 0
    for me, op in reversed(history):
        if op == 'C':
            run_c += 1
        else:
            break

    # Near endgame: exploit if opponent is generally cooperative
    if n >= 90:
        if opp_c >= opp_d * 2:
            return 'D'
        if recent_rate >= 0.7:
            return 'D'

    # Chronic defector: punish
    if defect_rate > 0.55:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Opponent just defected
    if last_op == 'D':
        # Long D streak: stay in defection
        if run_d >= 3:
            if rng.random() < 0.15:
                return 'C'
            return 'D'
        # Medium D streak
        if run_d == 2:
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        # Isolated defection against cooperative opponent: forgive sometimes
        if defect_rate < 0.25 and recent_rate >= 0.6:
            if rng.random() < 0.4:
                return 'C'
            return 'D'
        # Reciprocal punishment
        if rng.random() < 0.2:
            return 'C'
        return 'D'

    # Opponent just cooperated
    if last_op == 'C':
        # Long cooperative run: cooperate, occasional probe
        if run_c >= 4:
            if n < 90 and rng.random() < 0.08:
                return 'D'
            return 'C'
        # If we defected last and they cooperated back, return to cooperation
        if last_me == 'D':
            if defect_rate < 0.4:
                return 'C'
            if rng.random() < 0.7:
                return 'C'
            return 'D'
        # Mid-game cooperative state
        if defect_rate < 0.3:
            return 'C'
        # Mixed opponent: cooperate but watch
        if rng.random() < 0.88:
            return 'C'
        return 'D'

    return 'C'
